import { readFileSync } from 'fs'
const env=Object.fromEntries(readFileSync('.env.local','utf8').split('\n').filter(l=>l.includes('=')).map(l=>{const i=l.indexOf('=');return[l.slice(0,i).trim(),l.slice(i+1).trim()]}))
const URL_=env.NEXT_PUBLIC_SUPABASE_URL, SK=env.SUPABASE_SERVICE_ROLE_KEY
const SH={apikey:SK,Authorization:`Bearer ${SK}`,'Content-Type':'application/json'}
const PHONE='9000000007', PASS='testpass123', REASON='Multiple fake orders (test)'
const base='http://localhost:3000'

// cleanup any prior test row
await fetch(`${URL_}/rest/v1/consumers_auth?phone=eq.${PHONE}`,{method:'DELETE',headers:SH})

// 1. register
const reg=await fetch(`${base}/api/consumer/register`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:'Test User',phone:PHONE,password:PASS})})
console.log('1. register ->', reg.status, JSON.stringify(await reg.json()))

// 2. suspend via service-role with a reason
const sus=await fetch(`${URL_}/rest/v1/consumers_auth?phone=eq.${PHONE}`,{method:'PATCH',headers:{...SH,Prefer:'return=representation'},body:JSON.stringify({suspended:true,suspended_at:new Date().toISOString(),suspended_reason:REASON})})
console.log('2. suspended row ->', JSON.stringify((await sus.json()).map(r=>({suspended:r.suspended,reason:r.suspended_reason}))))

// 3. login attempt -> expect 403 with structured suspension
const log=await fetch(`${base}/api/consumer/login`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({phone:PHONE,password:PASS})})
const lj=await log.json()
console.log('3. login -> http', log.status)
console.log('   suspended       :', lj.suspended, '(expect true)')
console.log('   suspendedReason :', JSON.stringify(lj.suspendedReason), '(expect the reason)')

// 4. cleanup
await fetch(`${URL_}/rest/v1/consumers_auth?phone=eq.${PHONE}`,{method:'DELETE',headers:SH})
const chk=await fetch(`${URL_}/rest/v1/consumers_auth?phone=eq.${PHONE}&select=id`,{headers:SH})
console.log('4. cleanup -> remaining rows:', (await chk.json()).length, '(expect 0)')
EOF
